def subtract(a, b):
    def merge(intervals):
        intervals = [list(iv) for iv in intervals if iv[0] < iv[1]]
        intervals.sort(key=lambda x: x[0])
        merged = []
        for s, e in intervals:
            if merged and s <= merged[-1][1]:
                if e > merged[-1][1]:
                    merged[-1][1] = e
            else:
                merged.append([s, e])
        return merged

    a_merged = merge(a)
    b_merged = merge(b)

    result = []
    for s, e in a_merged:
        # find overlapping b intervals
        cur_start = s
        for bs, be in b_merged:
            if be <= cur_start:
                continue
            if bs >= e:
                break
            if bs > cur_start:
                result.append([cur_start, bs])
            cur_start = max(cur_start, be)
            if cur_start >= e:
                break
        if cur_start < e:
            result.append([cur_start, e])

    return merge(result)

